// ─── Combined database ────────────────────────────────────────────────────────
export const CLASS_DATABASE = [...SRD_BASE_CLASSES, ...PRESTIGE_CLASSES];

// ─── Lookup helpers ───────────────────────────────────────────────────────────
export const CLASS_BY_ID = Object.fromEntries(CLASS_DATABASE.map(c => [c.id, c]));
export const CLASS_BY_NAME = Object.fromEntries(CLASS_DATABASE.map(c => [c.name.toLowerCase(), c]));

export function getClassById(id) { return CLASS_BY_ID[id] || null; }
export function getClassByName(name) { return CLASS_BY_NAME[name?.toLowerCase()] || null; }

// Unique sources for filter UI
export const CLASS_SOURCES = [...new Set(CLASS_DATABASE.map(c => c.source))].sort();

// Base classes (Normal type) — shown first in class picker
export const BASE_CLASSES = CLASS_DATABASE.filter(c => c.classType === 'Normal');
export const PRESTIGE_CLASS_LIST = CLASS_DATABASE.filter(c => c.classType === 'Prestige');